     1	package hotel.reports;
     2	
     3	import hotel.reservations.Reservation;
     4	import java.util.List;
     5	
     6	/**
     7	 * Every report has the same shape: the title line (the inn, the report's name, the period), the header, one line
     8	 * per row, and the total line. Each report says only what changes: its name, its columns, which reservations
     9	 * count, its rows and its total.
    10	 */
    11	public abstract class CsvReport<P> {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	
    15	    public final String generate(P period) {
    16	        List<Reservation> selected = select(period);
    17	        StringBuilder csv = new StringBuilder();
    18	        csv.append(HOTEL_NAME).append(',').append(name()).append(',').append(period).append('\n');
    19	        csv.append(header()).append('\n');
    20	        for (String row : rows(selected)) {
    21	            csv.append(row).append('\n');
    22	        }
    23	        csv.append("total,").append(total(selected)).append('\n');
    24	        return csv.toString();
    25	    }
    26	
    27	    protected abstract String name();
    28	
    29	    protected abstract String header();
    30	
    31	    /** The reservations the report is about, in the report's order. */
    32	    protected abstract List<Reservation> select(P period);
    33	
    34	    protected abstract List<String> rows(List<Reservation> selected);
    35	
    36	    /** What comes after "total," on the last line. */
    37	    protected abstract String total(List<Reservation> selected);
    38	}
=== src/main/java/hotel/reports/OccupancyReport.java
     1	package hotel.reports;
     2	
     3	import hotel.reservations.Reservation;
     4	import hotel.reservations.ReservationStore;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.time.LocalDate;
     8	import java.util.Comparator;
     9	import java.util.List;
    10	
    11	/** Which rooms are occupied on a given night, for the front desk (CSV). */
    12	public final class OccupancyReport extends CsvReport<LocalDate> {
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	
    17	    public OccupancyReport(Rooms rooms, ReservationStore store) {
    18	        this.rooms = rooms;
    19	        this.store = store;
    20	    }
    21	
    22	    @Override
    23	    protected String name() {
    24	        return "occupancy";
    25	    }
    26	
    27	    @Override
    28	    protected String header() {
    29	        return "room,type,reservation,check_in,check_out";
    30	    }
    31	
    32	    @Override
    33	    protected List<Reservation> select(LocalDate night) {
    34	        return store.all().stream()
    35	                .filter(Reservation::isPaid)
    36	                .filter(reservation -> !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night))
    37	                .sorted(Comparator.comparingInt(Reservation::roomNumber))
    38	                .toList();
    39	    }
    40	
    41	    @Override
    42	    protected List<String> rows(List<Reservation> selected) {
    43	        return selected.stream().map(reservation -> {
    44	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
    45	            return room.number() + "," + room.type() + "," + reservation.id() + ","
    46	                    + reservation.checkIn() + "," + reservation.checkOut();
    47	        }).toList();
    48	    }
    49	
    50	    @Override
    51	    protected String total(List<Reservation> selected) {
    52	        return selected.size() + "/" + rooms.all().size();
    53	    }
    54	}
