     1	package hotel;
     2	
     3	import hotel.messages.EmailSender;
     4	import hotel.messages.SentMessages;
     5	import hotel.reports.OccupancyReport;
     6	import hotel.reports.RatePlanReport;
     7	import hotel.reports.RevenueReport;
     8	import hotel.reports.TourismTaxReport;
     9	import hotel.reservations.PriceCalculator;
    10	import hotel.reservations.ReservationService;
    11	import hotel.reservations.ReservationStore;
    12	import hotel.rooms.Rooms;
    13	import hotel.web.HttpApi;
    14	import io.javalin.Javalin;
    15	
    16	/** Puts the inn's pieces together and runs the HTTP server. */
    17	public final class Hotel {
    18	
    19	    private final Javalin server;
    20	
    21	    public Hotel() {
    22	        Rooms rooms = new Rooms();
    23	        ReservationStore store = new ReservationStore();
    24	        SentMessages sentMessages = new SentMessages();
    25	        ReservationService reservations =
    26	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
    27	        HttpApi api = new HttpApi(
    28	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store),
    29	                new TourismTaxReport(store), new RatePlanReport(store));
    30	        this.server = api.server();
    31	    }
    32	
    33	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
    34	    public int start(int port) {
    35	        server.start(port);
    36	        return server.port();
    37	    }
    38	
    39	    public void stop() {
    40	        server.stop();
    41	    }
    42	
    43	    public static void main(String[] args) {
    44	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    45	        new Hotel().start(port);
    46	    }
    47	}
