    83	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
    84	        server.post("/reservations/{id}/check-out", ctx ->
    85	                ctx.json(reservations.checkOut(reservationId(ctx))));
    86	        server.get("/reservations/{id}/document", ctx ->
    87	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
    88	
    89	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
    90	
    91	        server.get("/reports/occupancy", ctx -> {
    92	            LocalDate night = readDate(ctx);
    93	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
    94	        });
    95	        server.get("/reports/revenue", ctx -> {
    96	            YearMonth month = readMonth(ctx);
    97	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
    98	        });
    99	        server.get("/reports/tourism-tax", ctx -> {
   100	            YearMonth month = readMonth(ctx);
   101	            ctx.contentType("text/csv; charset=utf-8").result(tourismTaxReport.generate(month));
   102	        });
   103	        server.get("/reports/rate-plans", ctx -> {
