   109	    private void registerErrorHandling() {
   110	        server.exception(HotelException.class, (exception, ctx) -> {
   111	            ctx.status(httpStatus(exception.errorCode()));
   112	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
   113	        });
   114	    }
   115	
   116	    private static int httpStatus(ErrorCode errorCode) {
   117	        return switch (errorCode) {
   118	            case INVALID_REQUEST -> 400;
   119	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   120	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   121	            case CAPACITY_EXCEEDED -> 422;
   122	        };
   123	    }
