   125	    private static NewReservation readNewReservation(Context ctx) {
   126	        CreateReservationRequest body;
   127	        try {
   128	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   129	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   130	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   131	        }
   132	        if (body == null
   133	                || body.roomNumber() == null
   134	                || isBlank(body.guestName())
   135	                || isBlank(body.guestEmail())
   136	                || isBlank(body.guestCpf())
   137	                || body.checkIn() == null
   138	                || body.checkOut() == null
   139	                || body.guests() == null
   140	                || body.ratePlan() == null) {
   141	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   142	        }
   143	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
   144	        return new NewReservation(
   145	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
   146	    }
